import{_ as u,a0 as a,w as o,s as l,I as e,x as i,a1 as n,A as p,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"如何創建定製的 Ubuntu Live CD 鏡像 | LCTT x X-CMD","titleTemplate":false,"description":"如何創建定製的 Ubuntu Live CD 鏡像 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何創建定製的 Ubuntu Live CD 鏡像 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何創建定製的 Ubuntu Live CD 鏡像 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20171030 How To Create Custom Ubuntu Live CD Image","title":"如何創建定製的 Ubuntu Live CD 鏡像","tag":"201801","desc":""},"relativePath":"201801/20171030 How To Create Custom Ubuntu Live CD Image.md","filePath":"[post].md"}'),d={name:"201801/20171030 How To Create Custom Ubuntu Live CD Image.md"};function c(b,t,g,h,C,k){const s=a("Link");return o(),l("div",null,[t[24]||(t[24]=e("h1",{id:"如何創建定製的-ubuntu-live-cd-鏡像",tabindex:"-1"},[i("如何創建定製的 Ubuntu Live CD 鏡像 "),e("a",{class:"header-anchor",href:"#如何創建定製的-ubuntu-live-cd-鏡像","aria-label":"Permalink to “如何創建定製的 Ubuntu Live CD 鏡像”"},"​")],-1)),t[25]||(t[25]=e("p",null,[e("img",{src:"https://www.ostechnix.com/wp-content/uploads/2017/10/Cubic-720x340.png",alt:""})],-1)),e("p",null,[t[1]||(t[1]=i("今天讓我們來討論一下如何創建 Ubuntu Live CD 的定製鏡像（ISO）。我們以前可以使用 ",-1)),n(s,{href:"https://www.ostechnix.com/pinguy-builder-build-custom-ubuntu-os/"},{default:p(()=>[...t[0]||(t[0]=[i("Pinguy Builder",-1)])]),_:1}),t[2]||(t[2]=i(" 完成這項工作。但是，現在它似乎停止維護了。最近 Pinguy Builder 的官方網站似乎沒有任何更新。幸運的是，我找到了另一種創建 Ubuntu Live CD 鏡像的工具。使用 Cubic 即 ",-1)),t[3]||(t[3]=e("strong",null,"C",-1)),t[4]||(t[4]=i("ustom ",-1)),t[5]||(t[5]=e("strong",null,"Ub",-1)),t[6]||(t[6]=i("untu ",-1)),t[7]||(t[7]=e("strong",null,"I",-1)),t[8]||(t[8]=i("SO ",-1)),t[9]||(t[9]=e("strong",null,"C",-1)),t[10]||(t[10]=i("reator 的首字母縮寫，這是一個用來創建定製的可啓動的 Ubuntu Live CD（ISO）鏡像的 GUI 應用程序。",-1))]),t[26]||(t[26]=r(`<p>Cubic 正在積極開發，它提供了許多選項來輕鬆地創建一個定製的 Ubuntu Live CD ，它有一個集成的 chroot 命令列環境（LCTT 譯註：chroot —— Change Root，也就是改變程序執行時所參考的根目錄位置），在那裏你可以定製各種方面，比如安裝新的軟件包、內核，添加更多的背景壁紙，添加更多的文件和文件夾。它有一個直觀的 GUI 界面，在 live 鏡像創建過程中可以輕鬆的利用導航（可以利用點擊鼠標來回切換）。您可以創建一個新的自定義鏡像或修改現有的項目。因為它可以用來製作 Ubuntu live 鏡像，所以我相信它可以用在製作其他 Ubuntu 的發行版和衍生版鏡像中，比如 Linux Mint。</p><h3 id="安裝-cubic" tabindex="-1">安裝 Cubic <a class="header-anchor" href="#安裝-cubic" aria-label="Permalink to “安裝 Cubic”">​</a></h3><p>Cubic 的開發人員已經做出了一個 PPA 來簡化安裝過程。要在 Ubuntu 系統上安裝 Cubic ，在你的終端上運行以下命令:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-add-repository ppa:cubic-wizard/release</span></span>
<span class="line"><span>sudo apt-key adv --keyserver keyserver.ubuntu.com --recv-keys 6494C6D6997C215E</span></span>
<span class="line"><span>sudo apt update</span></span>
<span class="line"><span>sudo apt install cubic</span></span></code></pre></div><h3 id="利用-cubic-創建-ubuntu-live-cd-的定製鏡像" tabindex="-1">利用 Cubic 創建 Ubuntu Live CD 的定製鏡像 <a class="header-anchor" href="#利用-cubic-創建-ubuntu-live-cd-的定製鏡像" aria-label="Permalink to “利用 Cubic 創建 Ubuntu Live CD 的定製鏡像”">​</a></h3><p>安裝完成後，從應用程序菜單或 dock 啓動 Cubic。這是在我在 Ubuntu 16.04 LTS 桌面系統中 Cubic 的樣子。</p><p>為新項目選擇一個目錄。它是保存鏡像文件的目錄。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/10/Cubic-1.png" alt=""></p><p>請注意，Cubic 不是創建您當前系統的 Live CD 鏡像，而是利用 Ubuntu 的安裝 CD 來創建一個定製的 Live CD，因此，你應該有一個最新的 ISO 鏡像。</p><p>選擇您存儲 Ubuntu 安裝 ISO 鏡像的路徑。Cubic 將自動填寫您定製操作系統的所有細節。如果你願意，你可以改變細節。單擊 Next 繼續。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/10/Cubic-2.png" alt=""></p><p>接下來，來自源安裝介質中的壓縮的 Linux 文件系統將被提取到項目的目錄（在我們的例子中目錄的位置是 <code>/home/ostechnix/custom_ubuntu</code>)。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/10/Cubic-3.png" alt=""></p><p>一旦文件系統被提取出來，將自動加載到 chroot 環境。如果你沒有看到終端提示符，請按幾次回車鍵。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/10/Cubic-4.png" alt=""></p><p>在這裏可以安裝任何額外的軟件包，添加背景圖片，添加軟件源列表，添加最新的 Linux 內核和所有其他定製到你的 Live CD 。</p><p>例如，我希望 <code>vim</code> 安裝在我的 Live CD 中，所以現在就要安裝它。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/10/Cubic-6.png" alt=""></p><p>我們不需要使用 <code>sudo</code>，因為我們已經在具有最高權限（root）的環境中了。</p><p>類似地，如果需要，可以安裝更多的任何版本 Linux 內核。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apt install linux-image-extra-4.10.0-24-generic</span></span></code></pre></div><p>此外，您還可以更新軟件源列表（添加或刪除軟件存儲庫列表）：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/10/Cubic-5.png" alt=""></p><p>修改源列表後，不要忘記運行 <code>apt update</code> 命令來更新源列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apt update</span></span></code></pre></div><p>另外，您還可以向 Live CD 中添加文件或文件夾。複製文件或文件夾（右擊它們並選擇複製或者利用 <code>CTRL+C</code>），在終端右鍵單擊（在 Cubic 窗口內)，選擇 “Paste file(s)”，最後點擊 Cubic 嚮導底部的 “Copy”。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/10/Cubic-7.png" alt=""></p><p><strong>Ubuntu 17.10 用户注意事項</strong></p><blockquote><p>在 Ubuntu 17.10 系統中，DNS 查詢可能無法在 chroot 環境中工作。如果您正在製作一個定製的 Ubuntu 17.10 Live 鏡像，您需要指向正確的 <code>resolve.conf</code> 配置文件：</p></blockquote><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ln -sr /run/systemd/resolve/resolv.conf /run/systemd/resolve/stub-resolv.conf</span></span></code></pre></div><p>要驗證 DNS 解析工作，運行:</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/resolv.conf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ping</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> google.com</span></span></code></pre></div><p>如果你想的話，可以添加你自己的壁紙。要做到這一點，請切換到 <code>/usr/share/backgrounds/</code> 目錄，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd /usr/share/backgrounds</span></span></code></pre></div><p>並將圖像拖放到 Cubic 窗口中。或複製圖像，右鍵單擊 Cubic 終端窗口並選擇 “Paste file(s)” 選項。此外，確保你在 <code>/usr/share/gnome-backproperties</code> 的XML文件中添加了新的壁紙，這樣你可以在桌面上右鍵單擊新添加的圖像選擇 “Change Desktop Background” 進行交互。完成所有更改後，在 Cubic 嚮導中單擊 “Next”。</p><p>接下來，選擇引導到新的 Live ISO 鏡像時使用的 Linux 內核版本。如果已經安裝了其他版本內核，它們也將在這部分中被列出。然後選擇您想在 Live CD 中使用的內核。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/10/Cubic-8.png" alt=""></p><p>在下一節中，選擇要從您的 Live 映像中刪除的軟件包。在使用定製的 Live 映像安裝完 Ubuntu 操作系統後，所選的軟件包將自動刪除。在選擇要刪除的軟件包時，要格外小心，您可能在不知不覺中刪除了一個軟件包，而此軟件包又是另外一個軟件包的依賴包。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/10/Cubic-10-1.png" alt=""></p><p>接下來， Live 鏡像創建過程將開始。這裏所要花費的時間取決於你定製的系統規格。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/10/Cubic-12-1.png" alt=""></p><p>鏡像創建完成後後，單擊 “Finish”。Cubic 將顯示新創建的自定義鏡像的細節。</p><p>如果你想在將來修改剛剛創建的自定義 Live 鏡像，不要選擇“ Delete all project files, except the generated disk image and the corresponding MD5 checksum file”（除了生成的磁盤映像和相應的 MD5 校驗和文件之外，刪除所有的項目文件**） ，Cubic 將在項目的工作目錄中保留自定義圖像，您可以在將來進行任何更改。而不用從頭再來一遍。</p><p>要為不同的 Ubuntu 版本創建新的 Live 鏡像，最好使用不同的項目目錄。</p><h3 id="利用-cubic-修改-ubuntu-live-cd-的定製鏡像" tabindex="-1">利用 Cubic 修改 Ubuntu Live CD 的定製鏡像 <a class="header-anchor" href="#利用-cubic-修改-ubuntu-live-cd-的定製鏡像" aria-label="Permalink to “利用 Cubic 修改 Ubuntu Live CD 的定製鏡像”">​</a></h3><p>從菜單中啓動 Cubic ，並選擇一個現有的項目目錄。單擊 “Next” 按鈕，您將看到以下三個選項：</p><ol><li>Create a disk image from the existing project. （從現有項目創建一個磁盤映像。）</li><li>Continue customizing the existing project.（繼續定製現有項目。）</li><li>Delete the existing project.（刪除當前項目。）</li></ol><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/10/Cubic-13.png" alt=""></p><p>第一個選項將允許您從現有項目中使用之前所做的自定義設置創建一個新的 Live ISO 鏡像。如果您丟失了 ISO 鏡像，您可以使用第一個選項來創建一個新的。</p><p>第二個選項允許您在現有項目中進行任何其他更改。如果您選擇此選項，您將再次進入 chroot 環境。您可以添加新的文件或文件夾，安裝任何新的軟件，刪除任何軟件，添加其他的 Linux 內核，添加桌面背景等等。</p><p>第三個選項將刪除現有的項目，所以您可以從頭開始。選擇此選項將刪除所有文件，包括新生成的 ISO 鏡像文件。</p><p>我用 Cubic 做了一個定製的 Ubuntu 16.04 LTS 桌面 Live CD 。就像這篇文章裏描述的一樣。如果你想創建一個 Ubuntu Live CD， Cubic 可能是一個不錯的選擇。</p><p>就這些了，再會！</p><hr>`,54)),e("p",null,[t[12]||(t[12]=i("via: ",-1)),n(s,{href:"https://www.ostechnix.com/create-custom-ubuntu-live-cd-image/"},{default:p(()=>[...t[11]||(t[11]=[i("https://www.ostechnix.com/create-custom-ubuntu-live-cd-image/",-1)])]),_:1})]),e("p",null,[t[16]||(t[16]=i("作者：",-1)),n(s,{href:"https://www.ostechnix.com/author/sk/"},{default:p(()=>[...t[13]||(t[13]=[i("SK",-1)])]),_:1}),t[17]||(t[17]=i(" 譯者：",-1)),n(s,{href:"https://github.com/stevenzdg988"},{default:p(()=>[...t[14]||(t[14]=[i("stevenzdg988",-1)])]),_:1}),t[18]||(t[18]=i(" 校對：",-1)),n(s,{href:"https://github.com/wxy"},{default:p(()=>[...t[15]||(t[15]=[i("wxy",-1)])]),_:1})]),e("p",null,[t[21]||(t[21]=i("本文由 ",-1)),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[19]||(t[19]=[i("LCTT",-1)])]),_:1}),t[22]||(t[22]=i(" 原創編譯，",-1)),n(s,{href:"https://linux.cn/"},{default:p(()=>[...t[20]||(t[20]=[i("Linux中國",-1)])]),_:1}),t[23]||(t[23]=i(" 榮譽推出",-1))])])}const x=u(d,[["render",c]]);export{w as __pageData,x as default};
